package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;
import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.account.repository.AccountRepository;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true","greenocean.listener-support.queue-enabled=true"}) @ActiveProfiles("test")
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseN2ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_n2_race_"+UUID.randomUUID().toString().replace("-","");
 @org.springframework.test.context.DynamicPropertySource static void schema(org.springframework.test.context.DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerCalendar calendar;@Autowired ListenerBookings bookings;@Autowired ListenerSupportPolicy policy;@Autowired LiveSupportService live;@Autowired AccountRepository accounts;@Autowired PlatformTransactionManager manager;
 @Autowired ListenerQueue queue;@Autowired ListenerQueueCoverage coverage;
 List<PhaseIFixtures.Actor> extras=new ArrayList<>();PhaseIFixtures.Actor member,other,listener,staff;Instant start;UUID window;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);other=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);start=policy.now().plusSeconds(7200).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);window=calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",start.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),start.plusSeconds(14400).atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));coverage.approve(staff.id(),new ListenerQueueCoverage.Window(listener.id(),policy.now().minusSeconds(60),policy.now().plusSeconds(14400)));live.setAvailability(listener.id(),listener.session(),0,true,null);}
 @AfterEach void clean(){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT clock_timestamp() $$");var cleanup=new ArrayList<>(List.of(member,other,listener,staff));cleanup.addAll(extras);for(var a:cleanup)new TransactionTemplate(manager).execute(s->{accounts.erase(a.id());return null;});}
 ListenerBookings.Reservation in(Instant time,UUID key){return new ListenerBookings.Reservation(listener.id(),time,key,false);}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var go=new CountDownLatch(1);var x=pool.submit(()->{go.await();return outcome(a);});var y=pool.submit(()->{go.await();return outcome(b);});go.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 Object outcome(Supplier<?> f){try{return f.get();}catch(RuntimeException e){return e;}}
 long count(){return db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id IN(?,?) AND status='CONFIRMED'",Long.class,member.id(),other.id());}

 UUID join(PhaseIFixtures.Actor who,UUID key){return(UUID)queue.join(who.id(),new ListenerQueue.Admission(key,null,false)).get("id");}
 UUID join(){return join(member,UUID.randomUUID());}
 Map<String,Object> offered(UUID id){queue.work();return queue.view(id,member.id());}
 long offers(){return db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE status='OFFERED'",Long.class);}
 long open(){return db.queryForObject("SELECT count(*) FROM live_support_requests WHERE status IN('REQUESTED','ACCEPTED','ACTIVE','INTERRUPTED')",Long.class);}
 void clock(Instant at){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+at+"'::timestamptz $$");}
 void work(){queue.work();}
 <T>T tx(Supplier<T> f){return new TransactionTemplate(manager).execute(s->f.get());}
 PhaseIFixtures.Actor anotherListener(){var a=PhaseIFixtures.member(db,users,tokens);extras.add(a);PhaseIFixtures.review(db,a.id(),staff.id(),true);coverage.approve(staff.id(),new ListenerQueueCoverage.Window(a.id(),policy.now().minusSeconds(60),policy.now().plusSeconds(14400)));live.setAvailability(a.id(),a.session(),0,true,null);return a;}
 @Test @Tag("malicious") void twoWorkersOfferExactlyOnce()throws Exception{UUID id=join();var second=new ListenerQueue(policy,live);race(()->{work();return true;},()->tx(()->{second.work();return true;}));assertThat(offers()).isEqualTo(1);assertThat(queue.view(id,member.id()).get("status")).isEqualTo("OFFERED");assertThat(open()).isZero();}
 @Test @Tag("malicious") void twoMembersAndWorkersCannotShareOneListener()throws Exception{join();join(other,UUID.randomUUID());race(()->{work();return true;},()->{work();return true;});assertThat(offers()).isEqualTo(1);assertThat(open()).isZero();}
 @Test @Tag("malicious") void immediateRequestAndQueueAssignmentHaveOneCapacityWinner()throws Exception{join();race(()->{work();return true;},()->live.create(other.id(),UUID.randomUUID(),listener.id()));assertThat(offers()+open()).isEqualTo(1);}
 @Test @Tag("creative") void queueCancellationAndProposalReleaseAllPendingCapacity()throws Exception{UUID id=join();race(()->queue.cancel(id,member.id()),()->{work();return true;});assertThat(queue.view(id,member.id()).get("status")).isEqualTo("CANCELLED");assertThat(offers()).isZero();assertThat(open()).isZero();}
 @Test @Tag("malicious") void expiryAndReadinessRaceCannotCreateLateRequest()throws Exception{UUID id=join();var q=offered(id);clock(ListenerSupportPolicy.instant(q.get("allocation_expires_at")));race(()->queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id"))),()->{work();return true;});assertThat(queue.view(id,member.id()).get("status")).isEqualTo("EXPIRED");assertThat(open()).isZero();}
 @Test @Tag("creative") void sameMemberQueueingOnTwoDevicesRetainsOneDeadline()throws Exception{UUID key=UUID.randomUUID();var result=race(()->queue.join(member.id(),new ListenerQueue.Admission(key,null,false)),()->queue.join(member.id(),new ListenerQueue.Admission(key,null,false)));assertThat(result).allMatch(Map.class::isInstance);assertThat(((Map<?,?>)result.getFirst()).get("id")).isEqualTo(((Map<?,?>)result.getLast()).get("id"));assertThat(((Map<?,?>)result.getFirst()).get("expires_at")).isEqualTo(((Map<?,?>)result.getLast()).get("expires_at"));}
 @Test @Tag("creative") void restartedWorkerRetainsAllocationAndIndependentSingleTransfer(){UUID id=join();var q=offered(id);var second=new ListenerQueue(policy,live);var recovered=tx(()->second.get(id,member.id()));assertThat(recovered.get("allocation_id")).isEqualTo(q.get("allocation_id"));var confirmation=new ListenerQueue.Confirmation((UUID)q.get("allocation_id"));var first=tx(()->second.confirm(id,member.id(),confirmation));var retry=queue.confirm(id,member.id(),confirmation);assertThat(((LiveSupportView)first.get("request")).id()).isEqualTo(((LiveSupportView)retry.get("request")).id());assertThat(open()).isEqualTo(1);assertThat(offers()).isZero();}
 @Test @Tag("malicious") void revocationAndQueueReadinessCannotLeaveAuthorizedHandoff()throws Exception{UUID id=join();var q=offered(id);race(()->queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id"))),()->{db.update("UPDATE listener_live_authorizations SET revoked_at=clock_timestamp() WHERE listener_id=?",listener.id());return true;});live.reconcile();assertThat(open()).isZero();assertThat(queue.view(id,member.id()).get("status")).isIn("TRANSFERRED","SAFETY_TERMINATED");}
 @Test @Tag("malicious") void queueProposalAndNearTermBookingCannotOverlap()throws Exception{UUID id=join();Instant near=policy.now().plusSeconds(1860).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",near.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),near.plusSeconds(3600).atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));race(()->{work();return true;},()->bookings.reserve(other.id(),in(near,UUID.randomUUID())));assertThat(offers()+count()).isEqualTo(1);assertThat(open()).isZero();}
 @Test @Tag("malicious") void twoReadinessConfirmationsCreateExactlyOnePhaseIRequest()throws Exception{UUID id=join();var q=offered(id);var c=new ListenerQueue.Confirmation((UUID)q.get("allocation_id"));var result=race(()->queue.confirm(id,member.id(),c),()->queue.confirm(id,member.id(),c));assertThat(result).allMatch(Map.class::isInstance);assertThat(open()).isEqualTo(1);assertThat(((LiveSupportView)((Map<?,?>)result.getFirst()).get("request")).id()).isEqualTo(((LiveSupportView)((Map<?,?>)result.getLast()).get("request")).id());}
 @Test @Tag("creative") void cancelVersusTransferLeavesNoPendingLiveRequest()throws Exception{UUID id=join();var q=offered(id);race(()->queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id"))),()->queue.cancel(id,member.id()));assertThat(open()).isZero();assertThat(offers()).isZero();assertThat(db.queryForObject("SELECT count(*) FROM live_support_requests WHERE conversation_id IS NOT NULL",Integer.class)).isZero();}
 @Test @Tag("creative") void checkinAndCancellationHaveOneTerminalOutcome()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");clock(start.minusSeconds(300));race(()->bookings.checkin(id,member.id()),()->bookings.cancel(id,listener.id()));assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("CANCELLED_BY_LISTENER");assertThat(open()).isZero();}
 @Test @Tag("malicious") void scheduledHandoffAndRevocationCannotLeaveLiveAccess()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");clock(start);bookings.checkin(id,member.id());race(()->bookings.handoff(id,member.id()),()->{db.update("UPDATE listener_live_authorizations SET revoked_at=clock_timestamp() WHERE listener_id=?",listener.id());return true;});bookings.reconcile();assertThat(open()).isZero();assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("CANCELLED_BY_SERVICE");}
 @Test @Tag("confused") void noShowAndLateCheckinCannotReviveReservation()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");clock(start.plusSeconds(600));race(()->bookings.checkin(id,member.id()),()->{bookings.reconcile();return true;});assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("MEMBER_NO_SHOW");assertThat(open()).isZero();}
 @Test @Tag("malicious") void scheduledCheckinAndQueueAssignmentUseDifferentEligibleCapacity()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");clock(start.minusSeconds(300));var extra=anotherListener();UUID queued=join(other,UUID.randomUUID());race(()->bookings.checkin(id,member.id()),()->{work();return true;});assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("CHECKED_IN");assertThat(queue.view(queued,other.id()).get("status")).isEqualTo("OFFERED");assertThat(db.queryForObject("SELECT listener_id FROM listener_wait_queue WHERE id=?",UUID.class,queued)).isEqualTo(extra.id());assertThat(open()).isZero();}
}
